<?php
namespace App\Http\Controllers; use App\Models\User; use App\Notifications\AfhmNotification; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class AssignmentController extends Controller { public function edit(){return view('assignments.edit',['teachers'=>User::teachers()->get(),'supervisors'=>User::supervisors()->active()->get()]);} public function update(Request $r){$d=$r->validate(['teacher_id'=>['required',Rule::exists('users','id')->where(fn($q)=>$q->where('role','teacher')->where('is_active',true))],'supervisor_id'=>['required','different:teacher_id',Rule::exists('users','id')->where(fn($q)=>$q->where('role','supervisor')->where('is_active',true))]]);$teacher=User::findOrFail($d['teacher_id']);$supervisor=User::findOrFail($d['supervisor_id']);$assigned=User::whereKey($teacher->id)->whereNull('supervisor_id')->update(['supervisor_id'=>$supervisor->id]);if(!$assigned){return back()->withInput()->withErrors(['teacher_id'=>__('This teacher is already assigned to a supervisor.')]);}$supervisor->notify(new AfhmNotification("{$teacher->name} has been assigned to you."));return back()->with('success','Supervisor assigned successfully.');}}
